ALTER TABLE public.menu_items ADD COLUMN photo_urls text[] NOT NULL DEFAULT '{}'; ALTER TABLE public.menu_items ADD CONSTRAINT menu_items_four_photos CHECK (cardinality(photo_urls) <= 4); UPDATE public.menu_items SET photo_urls = ARRAY[photo_url] WHERE photo_url IS NOT NULL; ALTER TABLE public.commerce_campaigns ADD COLUMN banner_image_url text; COMMENT ON COLUMN public.menu_items.photo_urls IS 'Up to four item gallery images; photo_url remains the primary catalog image.'; COMMENT ON COLUMN public.commerce_campaigns.banner_image_url IS 'Admin-uploaded campaign cover artwork.';